{
  "claims": [
    {
      "claim": "The bill proposes to increase the amount for teachers' supplies in Tennessee Code Annotated Section 49-3-359(a) from $200 to $500.",
      "summary_quote": "This bill proposes to increase the amount for teachers' supplies in Tennessee Code Annotated Section 49-3-359(a) from $200 to $500.",
      "verdict": "supported",
      "source_quote": "SECTION 1. Tennessee Code Annotated, Section 49-3-359(a), is amended by deleting\n\n\"two hundred dollars ($200)\" and substituting \"five hundred dollars ($500)\".",
      "error_type": "none",
      "rationale": "Section 1 makes the stated dollar substitution in the identified subsection; the bill's title identifies its subject as funding for teachers' supplies."
    },
    {
      "claim": "The bill is not an appropriation of funds.",
      "summary_quote": "The bill states that it is not an appropriation of funds",
      "verdict": "supported",
      "source_quote": "This act is not an appropriation of funds",
      "error_type": "none",
      "rationale": "Section 2 expressly states that the act does not appropriate funds."
    },
    {
      "claim": "Money cannot be spent pursuant to the bill unless specifically appropriated by the General Appropriations Act.",
      "summary_quote": "money cannot be spent unless it is specifically appropriated by the General Appropriations Act",
      "verdict": "supported",
      "source_quote": "funds shall not be obligated\n\nor expended pursuant to this act unless the funds are specifically appropriated by the General\n\nAppropriations Act.",
      "error_type": "none",
      "rationale": "In context, the summary describes spending pursuant to this bill and accurately states the specific-appropriation condition."
    },
    {
      "claim": "If enacted, the change would take effect July 1, 2025.",
      "summary_quote": "If passed, this change would take effect on July 1, 2025.",
      "verdict": "supported",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "Section 3 specifies the stated effective date."
    }
  ]
}
